from target import daily_revenue


def test_single_record_is_counted_once():
    assert daily_revenue([{"day": "2024-03-10", "amount": 100}], "2024-03-10") == 100


def test_other_day_is_ignored():
    assert daily_revenue([{"day": "2024-03-09", "amount": 100}], "2024-03-10") == 0


def test_two_records_are_summed_once_each():
    records = [
        {"day": "2024-03-10", "amount": 100},
        {"day": "2024-03-10", "amount": 200},
    ]
    assert daily_revenue(records, "2024-03-10") == 300
